/**
 * @file Service worker of the web app: makes it installable and usable offline.
 *
 * Strategy: network-first for every same-origin GET (so the catalog and code are
 * always fresh when online), falling back to the cache when offline. The cache
 * name contains the app version, replaced by build_web.py, so old caches are
 * dropped on update. import.js is never cached (it runs on dl.tntu.edu.ua).
 */
const CACHE = "vybirkovi-__VERSION__";
/** App shell pre-cached on install (list generated by build_web.py). */
const PRECACHE = __PRECACHE__;

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener("fetch", e => {
  const url = new URL(e.request.url);
  if (e.request.method !== "GET" || url.origin !== location.origin || url.pathname.endsWith("/import.js")) return;
  e.respondWith(
    fetch(e.request)
      .then(res => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(e.request, copy)); }
        return res;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }).then(r => r || caches.match("./")))
  );
});
